{"command": "cd /workspace && cat <<'EOF' > /tmp/T.py
#!/usr/bin/env python3
import subprocess,time,re,sys,os
def sh(cmd): return subprocess.run(cmd,capture_output=True,text=True).stdout
def new(prompt,secs,cols=200,rows=40):
    sh(['tmux','kill-server'])
    time.sleep(0.3)
    sh(['tmux','-f','/dev/null','new-session','-d','-s','tt','-x',str(cols),'-y',str(rows),
        f"cd /workspace && ./executable -p '{prompt}' {('-s %s'%secs) if secs else ''} ; sleep 120"])
    time.sleep(1.2)
def cap():
    return sh(['tmux','capture-pane','-t','tt','-p'])
def countdown():
    c=cap()
    m=[l for l in c.split('\n') if re.search(r'\d+\.\d\s*$', l.strip())]
    return m[-1].strip() if m else '?'
def typed():
    c=sh(['tmux','capture-pane','-t','tt','-e','-p'])
    for l in c.split('\n'):
        t=re.sub(r'\x1b\[[0-9;]*m','',l)
        if t.strip() and 'wpm' not in t and 'retry' not in t and len(t.strip())>3:
            n=len(re.findall(r'\x1b\[1m\x1b\[38;5;2m',l)) + len(re.findall(r'\x1b\[38;5;1m',l))
            return n
    return None
def keys(times,char='a'):
    t0=time.time(); ki=0
    while ki<len(times):
        now=time.time()-t0
        if now>=times[ki]:
            sh(['tmux','send-keys','-t','tt',char]); ki+=1
            continue
        time.sleep(0.02)
def result():
    c=cap()
    rows=[]
    for i,l in enumerate(c.split('\n')):
        t=re.sub(r'\x1b\[[0-9;]*m','',l.rstrip('\n'))
        brl=[j for j,c2 in enumerate(t) if 0x2800<=ord(c2)<=0x28FF]
        if brl or '│' in t or 'wpm' in t and i<20:
            rows.append((i,len(t)-len(t.lstrip()),t.strip()))
    return rows
def stats():
    c=cap()
    for l in c.split('\n'):
        t=re.sub(r'\x1b\[[0-9;]*m','',l)
        if re.search(r'\d+ wpm',t): return t.strip()
    return '?'
def xlabels():
    c=cap()
    for l in c.split('\n'):
        t=re.sub(r'\x1b\[[0-9;]*m','',l.rstrip('\n'))
        if re.search(r'\d+\.\d\d\s*$',t) and 'wpm' not in t:
            s=t.strip(); return [s.split()[0], s.split()[-1]]
    return ['?','?']
def logline():
    return sh(['tail','-1','/home/agent/.config/thokr/log.csv']).strip()
EOF
