use std::process::exit;

pub const VERSION: &str = "thokr 0.4.1";
pub const ABOUT: &str = "sleek typing tui with visualized results and historical logging";

#[derive(Clone, Copy, PartialEq)]
pub enum Lang {
    English,
    English1k,
    English10k,
}

impl Lang {
    pub fn name(&self) -> &'static str {
        match self {
            Lang::English => "english",
            Lang::English1k => "english1k",
            Lang::English10k => "english10k",
        }
    }
    pub fn words(&self) -> &'static str {
        match self {
            Lang::English => include_str!("words/english.txt"),
            Lang::English1k => include_str!("words/english1k.txt"),
            Lang::English10k => include_str!("words/english10k.txt"),
        }
    }
}

pub struct Args {
    pub full_sentences: Option<usize>,
    pub lang: Lang,
    pub prompt: Option<String>,
    pub secs: Option<usize>,
    pub num_words: usize,
}

struct Opt {
    short: char,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    default: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
}

const OPTS: &[Opt] = &[
    Opt { short: 'f', long: "full-sentences", value: Some("NUMBER_OF_SENTENCES"),
          help: "number of sentences to use in test", default: None, possible: None },
    Opt { short: 'h', long: "help", value: None, help: "Print help information",
          default: None, possible: None },
    Opt { short: 'l', long: "supported-language", value: Some("SUPPORTED_LANGUAGE"),
          help: "language to pull words from", default: Some("english"),
          possible: Some(&["english", "english1k", "english10k"]) },
    Opt { short: 'p', long: "prompt", value: Some("PROMPT"), help: "custom prompt to use",
          default: None, possible: None },
    Opt { short: 's', long: "number-of-secs", value: Some("NUMBER_OF_SECS"),
          help: "number of seconds to run test", default: None, possible: None },
    Opt { short: 'V', long: "version", value: None, help: "Print version information",
          default: None, possible: None },
    Opt { short: 'w', long: "number-of-words", value: Some("NUMBER_OF_WORDS"),
          help: "number of words to use in test", default: Some("15"), possible: None },
];

fn opt_by_long(l: &str) -> Option<&'static Opt> { OPTS.iter().find(|o| o.long == l) }
fn opt_by_short(c: char) -> Option<&'static Opt> { OPTS.iter().find(|o| o.short == c) }

fn is_terminal(fd: i32) -> bool {
    unsafe { libc_isatty(fd) != 0 }
}
extern "C" { fn isatty(fd: i32) -> i32; }
fn libc_isatty(fd: i32) -> i32 { unsafe { isatty(fd) } }

fn term_width() -> usize {
    if is_terminal(1) {
        // ioctl TIOCGWINSZ
        let mut ws = libc_winsize { row: 0, col: 0, x: 0, y: 0 };
        unsafe {
            if libc_ioctl(1, 0x5413, &mut ws as *mut libc_winsize) == 0 && ws.col > 0 {
                return ws.col as usize;
            }
        }
    }
    80
}

#[repr(C)]
struct libc_winsize { row: u16, col: u16, x: u16, y: u16 }
extern "C" { fn ioctl(fd: i32, req: i64, ...) -> i32; }

fn colorize(s: &str, code: &str) -> String {
    if is_terminal(1) {
        format!("\x1b[{}m{}\x1b[39m", code, s)
    } else {
        s.to_string()
    }
}
fn err_colorize(s: &str, code: &str, bold: bool) -> String {
    if is_terminal(2) {
        let b = if bold { "\x1b[1m" } else { "" };
        format!("{}{}\x1b[0m\x1b[39m\x1b[49m{}", b, s, "")
    } else {
        s.to_string()
    }
}

fn err_style(prefix: &str, code: &str) -> String {
    if is_terminal(2) {
        format!("\x1b[1m{}\x1b[0m\x1b[39m\x1b[49m", code.replace('X', prefix))
    } else {
        prefix.to_string()
    }
}

// Wraps a plain-text string to a max width, greedily on spaces; hard-breaks
// over-long words like clap does.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut curw = 0usize;
    for word in text.split(' ') {
        let w = word.chars().count();
        if curw == 0 {
            if w > width {
                let mut rest = word;
                while rest.chars().count() > width {
                    let head: String = rest.chars().take(width).collect();
                    out.push(head);
                    rest = rest.chars().skip(width).collect();
                }
                cur = rest.to_string();
                curw = rest.chars().count();
            } else {
                cur = word.to_string();
                curw = w;
            }
        } else if curw + 1 + w <= width {
            cur.push(' ');
            cur.push_str(word);
            curw += 1 + w;
        } else {
            out.push(std::mem::take(&mut cur));
            if w > width {
                let mut rest = word;
                while rest.chars().count() > width {
                    let head: String = rest.chars().take(width).collect();
                    out.push(head);
                    rest = rest.chars().skip(width).collect();
                }
                cur = rest.to_string();
                curw = rest.chars().count();
            } else {
                cur = word.to_string();
                curw = w;
            }
        }
    }
    if !cur.is_empty() { out.push(cur); }
    if out.is_empty() { out.push(String::new()); }
    out
}

fn help_text(bin: &str) -> String {
    let width = term_width();
    let mut out = String::new();
    out.push_str(&format!("{} {}\n", colorize("thokr", "32"), VERSION.split_once(' ').unwrap().1));
    out.push_str(&wrap(ABOUT, width).join("\n"));
    out.push('\n');
    out.push_str(&format!("{}\n", colorize("USAGE:", "33")));
    out.push_str(&format!("    {} [OPTIONS]\n\n", bin));
    out.push_str(&format!("{}\n", colorize("OPTIONS:", "33")));
    for (i, o) in OPTS.iter().enumerate() {
        let mut head = format!("    {}, --{}", colorize(&format!("-{}", o.short), "32"), colorize(&format!("--{}", o.long), "32"));
        if let Some(v) = o.value {
            head.push_str(&format!(" {}", colorize(&format!("<{}>", v), "32")));
        }
        out.push_str(&head);
        out.push('\n');
        // body: help + default + possible values
        let mut body = String::from(o.help);
        if let Some(d) = o.default {
            body.push_str(&format!(" [default: {}]", d));
        }
        if let Some(p) = o.possible {
            body.push_str(&format!(" [possible values: {}]", p.join(", ")));
        }
        for line in wrap(&body, width - 12) {
            out.push_str(&format!("            {}\n", line));
        }
        if i + 1 < OPTS.len() { out.push('\n'); }
    }
    out
}

fn usage_block(bin: &str, smart: Option<&str>) -> String {
    let mut s = String::from("\nUSAGE:\n    ");
    match smart {
        Some(x) => s.push_str(&format!("{} {}\n", bin, x)),
        None => s.push_str(&format!("{} [OPTIONS]\n", bin)),
    }
    s
}

fn fail(msg: &str, bin: &str, smart: Option<&str>) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} {}\n", err_red_bold("error:"), msg));
    out.push_str(&usage_block(bin, smart));
    out.push_str(&format!("\nFor more information try {}\n", green_err("--help")));
    eprint!("{}", out);
    exit(2);
}

fn err_red_bold(s: &str) -> String {
    if is_terminal(2) { format!("\x1b[1m\x1b[31m{}\x1b[0m\x1b[39m\x1b[49m", s) } else { s.to_string() }
}
fn green_err(s: &str) -> String {
    if is_terminal(2) { format!("\x1b[32m{}\x1b[39m", s) } else { s.to_string() }
}
fn yellow_err(s: &str) -> String {
    if is_terminal(2) { format!("\x1b[33m{}\x1b[39m", s) } else { s.to_string() }
}

fn print_error(bin: &str, args: &[String], smart: Option<&str>) -> ! {
    let mut out = String::new();
    let arg = &args[0];
    let bad = yellow_err(arg);
    out.push_str(&format!("{} Found argument '{}' which wasn't expected, or isn't valid in this context\n",
                          err_red_bold("error:"), bad));
    let mut hints: Vec<String> = Vec::new();
    // did you mean?
    let cands: Vec<&str> = if arg.starts_with("--") {
        OPTS.iter().map(|o| format!("--{}", o.long)).collect()
    } else if arg.starts_with('-') {
        OPTS.iter().map(|o| format!("-{}", o.short)).collect()
    } else { vec![] };
    let mut best: Option<(usize, &str)> = None;
    for c in &cands {
        let d = jaro_like(arg, c);
        if let Some((bd, _)) = best {
            if d < bd { best = Some((d, c)); }
        } else { best = Some((d, c)); }
    }
    if let Some((d, c)) = best {
        if d >= 0.7 {
            hints.push(format!("\tDid you mean '{}'?\n", green_err(c)));
            return_fail_with_hint(bin, &mut out, hints, smart_for(c));
        }
    }
    if arg.starts_with('-') && args.len() == 1 {
        hints.push(format!("\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n", arg, arg));
    }
    return_fail_with_hint(bin, &mut out, hints, smart)
}

fn return_fail_with_hint(bin: &str, out: &mut String, hints: Vec<String>, smart: Option<&str>) -> ! {
    for h in hints {
        out.push('\n');
        out.push_str(&h);
    }
    out.push_str(&usage_block(bin, smart));
    out.push_str(&format!("\nFor more information try {}\n", green_err("--help")));
    eprint!("{}", out);
    exit(2);
}

fn smart_for(s: &str) -> Option<&'static str> {
    if s == "--version" { Some("--version") } else { None }
}

fn jaro_like(a: &str, b: &str) -> f64 {
    // simple similarity: 1 - levenshtein/max_len
    let la: Vec<char> = a.chars().collect();
    let lb: Vec<char> = b.chars().collect();
    let m = la.len().max(lb.len());
    if m == 0 { return 1.0; }
    let n = la.len().min(lb.len());
    let mut same = 0;
    for i in 0..n {
        if la[i] == lb[i] { same += 1; }
    }
    same as f64 / m as f64
}

pub fn parse() -> Args {
    let argv: Vec<String> = std::env::args().collect();
    let bin = argv.first().map(|s| {
        std::path::Path::new(s).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| s.clone())
    }).unwrap_or_else(|| "thokr".to_string());
    let args: Vec<String> = argv.into_iter().skip(1).collect();

    let mut full_sentences: Option<usize> = None;
    let mut secs: Option<usize> = None;
    let mut prompt: Option<String> = None;
    let mut lang: Option<String> = None;
    let mut num_words: Option<usize> = None;
    let mut seen: Vec<&str> = Vec::new();
    let mut i = 0usize;
    let mut only_positional = false;

    while i < args.len() {
        let a = args[i].clone();
        if !only_positional && a == "--" {
            only_positional = true;
            i += 1;
            continue;
        }
        if !only_positional && a.starts_with("--") {
            let (name, inline) = match a[2..].split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (a[2..].to_string(), None),
            };
            if name == "help" {
                print!("{}", help_text(&bin));
                exit(0);
            }
            if name == "version" {
                println!("{}", VERSION);
                exit(0);
            }
            match opt_by_long(&name) {
                None => {
                    print_error(&bin, &[a], None);
                }
                Some(o) => {
                    let val = match inline {
                        Some(v) => v,
                        None => {
                            i += 1;
                            if i >= args.len() {
                                missing_value(&bin, o, false);
                            }
                            args[i].clone()
                        }
                    };
                    store(o, &val, &bin, &mut full_sentences, &mut secs, &mut prompt, &mut lang, &mut num_words, &mut seen);
                    i += 1;
                }
            }
            continue;
        }
        if !only_positional && a.starts_with('-') && a.len() > 1 {
            // short options, possibly bundled
            let chars: Vec<char> = a.chars().skip(1).collect();
            let mut j = 0usize;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                if c == 'h' {
                    print!("{}", help_text(&bin));
                    exit(0);
                }
                if c == 'V' {
                    println!("{}", VERSION);
                    exit(0);
                }
                match opt_by_short(c) {
                    None => {
                        let bad: String = std::iter::once('-').chain(chars[j..].iter().copied()).collect();
                        print_error(&bin, &[bad], None);
                    }
                    Some(o) => {
                        if o.value.is_some() {
                            let rest: String = chars[j + 1..].iter().collect();
                            let val = if !rest.is_empty() {
                                rest
                            } else {
                                i += 1;
                                if i >= args.len() {
                                    missing_value(&bin, o, true);
                                }
                                consumed_next = true;
                                args[i].clone()
                            };
                            store(o, &val, &bin, &mut full_sentences, &mut secs, &mut prompt, &mut lang, &mut num_words, &mut seen);
                            j = chars.len();
                        } else {
                            j += 1;
                        }
                    }
                }
            }
            if !consumed_next { i += 1; }
            continue;
        }
        // positional
        print_error(&bin, &[a], None);
    }

    let lang = match lang {
        None => Lang::English,
        Some(s) => match s.as_str() {
            "english" => Lang::English,
            "english1k" => Lang::English1k,
            "english10k" => Lang::English10k,
            _ => unreachable!(),
        },
    };
    Args { full_sentences, lang, prompt, secs, num_words: num_words.unwrap_or(15) }
}

fn missing_value(bin: &str, o: &'static Opt, _short: bool) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} The argument '{}' requires a value but none was supplied\n",
                          err_red_bold("error:"), yellow_err(&format!("--{} <{}>", o.long, o.value.unwrap()))));
    if let Some(p) = o.possible {
        let vals: Vec<String> = p.iter().map(|v| green_err(v)).collect();
        out.push_str(&format!("\t[possible values: {}]\n", vals.join(", ")));
    }
    out.push_str(&usage_block(bin, None));
    out.push_str(&format!("\nFor more information try {}\n", green_err("--help")));
    eprint!("{}", out);
    exit(2);
}

#[allow(clippy::too_many_arguments)]
fn store(o: &'static Opt, val: &str, bin: &str,
         full_sentences: &mut Option<usize>, secs: &mut Option<usize>,
         prompt: &mut Option<String>, lang: &mut Option<String>,
         num_words: &mut Option<usize>, seen: &mut Vec<&'static str>) {
    if seen.contains(&o.long) {
        let mut out = String::new();
        out.push_str(&format!("{} The argument '{}' was provided more than once, but cannot be used multiple times\n",
                              err_red_bold("error:"), yellow_err(&format!("--{} <{}>", o.long, o.value.unwrap_or("")))));
        out.push_str(&usage_block(bin, None));
        out.push_str(&format!("\nFor more information try {}\n", green_err("--help")));
        eprint!("{}", out);
        exit(2);
    }
    seen.push(o.long);
    match o.long {
        "full-sentences" => { *full_sentences = Some(parse_num(val, o, bin, false)); }
        "number-of-secs" => { *secs = Some(parse_num(val, o, bin, false)); }
        "number-of-words" => { *num_words = Some(parse_num(val, o, bin, false)); }
        "prompt" => { *prompt = Some(val.to_string()); }
        "supported-language" => {
            if let Some(p) = o.possible {
                if !p.contains(&val) {
                    let mut out = String::new();
                    out.push_str(&format!("{} \"{}\" isn't a valid value for '{}'\n",
                                          err_red_bold("error:"), val,
                                          yellow_err(&format!("--{} <{}>", o.long, o.value.unwrap()))));
                    let vals: Vec<String> = p.iter().map(|v| green_err(v)).collect();
                    out.push_str(&format!("\t[possible values: {}]\n", vals.join(", ")));
                    out.push_str(&usage_block(bin, Some(&format!("--{} <{}>", o.long, o.value.unwrap()))));
                    out.push_str(&format!("\nFor more information try {}\n", green_err("--help")));
                    eprint!("{}", out);
                    exit(2);
                }
                *lang = Some(val.to_string());
            }
        }
        _ => {}
    }
}

fn parse_num(val: &str, o: &'static Opt, bin: &str, _short: bool) -> usize {
    match val.parse::<usize>() {
        Ok(v) => v,
        Err(e) => {
            let reason = if val.chars().all(|c| c.is_ascii_digit()) && val.len() > 19 {
                "number too large to fit in target type"
            } else {
                "invalid digit found in string"
            };
            let _ = e;
            let _ = bin;
            let mut out = String::new();
            out.push_str(&format!("{} Invalid value \"{}\" for '{}': {}\n",
                                  err_red_bold("error:"), val,
                                  yellow_err(&format!("--{} <{}>", o.long, o.value.unwrap())),
                                  reason));
