fn wrap_lines(text: &[char], width: usize) -> Vec<Vec<char>> {
    let mut out: Vec<Vec<char>> = Vec::new();
    if width == 0 { out.push(text.to_vec()); return out; }
    let mut cur: Vec<char> = Vec::new();
    let mut i = 0usize;
    while i < text.len() {
        if text[i] == ' ' {
            if !cur.is_empty() && cur.len() + 1 > width {
                out.push(std::mem::take(&mut cur));
            } else if !cur.is_empty() {
                cur.push(' ');
            }
            i += 1;
            continue;
        }
        // gather a word
        let start = i;
        while i < text.len() && text[i] != ' ' { i += 1; }
        let word: Vec<char> = text[start..i].to_vec();
        if cur.len() + word.len() <= width {
            cur.extend(word);
        } else {
            if !cur.is_empty() { out.push(std::mem::take(&mut cur)); }
            if word.len() > width {
                for chunk in word.chunks(width) {
                    if chunk.len() == word.len() % width + width { }
                    out.push(chunk.to_vec());
                }
            } else {
                cur = word;
            }
        }
    }
    if !cur.is_empty() { out.push(cur); }
    if out.is_empty() { out.push(Vec::new()); }
    out
}

fn base_y(h: u16, n: usize) -> u16 {
    let c = if n <= 1 { 1 } else { n + 1 };
    ((h as i32 - c as i32) / 2).max(0) as u16
}

fn draw_test(f: &mut Frame, area: Rect, app: &App) {
    let w = area.width as usize;
    let maxw = if w > 10 { w - 10 } else { 1 };
    let lines = wrap_lines(&app.prompt, maxw);
    let n = lines.len();
    let blockw = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    let x = (w as f64 / 2.0) as usize - (blockw as f64 / 2.0) as usize;
    let y = base_y(area.height, n);
    let has_timer = app.secs.is_some();
    let py = y + if has_timer { 2 } else { 0 };
    if has_timer {
        let remaining = match (app.start, app.secs) {
            (Some(s), Some(v)) => (v as f64 - s.elapsed().as_secs_f64()).max(0.0),
            _ => app.secs.unwrap() as f64,
        };
        let s = format!("{:.1}", remaining);
        let sw = s.chars().count();
        let tx = (area.width as f64 / 2.0) as usize - (sw as f64 / 2.0) as usize;
        let style = Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM);
        let line = Line::from(Span::styled(s, style));
        f.render_widget(line, Rect::new(tx as u16, y, area.width, 1));
    }
    for (i, l) in lines.iter().enumerate() {
        if py + i as u16 >= area.height { break; }
        let mut spans: Vec<Span> = Vec::new();
        let mut col = 0usize;
        for (j, ch) in l.iter().enumerate() {
            let idx = i * 0 + j; // absolute index handled below
            let _ = idx;
            let abs = absolute_index(&lines, i, j);
            let style = if abs < app.typed.len() {
                if app.typed[abs] == *ch {
                    Style::default().fg(GREEN).add_modifier(Modifier::BOLD)
                } else {
                    let shown = if *ch == ' ' { '\u{00b7}' } else { *ch };
                    col += 0;
                    spans.push(Span::styled(shown.to_string(), Style::default().fg(RED).add_modifier(Modifier::BOLD)));
                    continue;
                }
            } else if abs == app.typed.len() {
                Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM).add_modifier(Modifier::UNDERLINE)
            } else {
                Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM)
            };
            spans.push(Span::styled(ch.to_string(), style));
        }
        let line = Line::from(spans);
        f.render_widget(line, Rect::new(x as u16, (py + i) as u16, area.width, 1));
    }
}

fn absolute_index(lines: &Vec<Vec<char>>, li: usize, j: usize) -> usize {
    let mut n = 0;
    for (k, l) in lines.iter().enumerate() {
        if k < li { n += l.len() + 1; } else { return n + j; }
    }
    n + j
}

fn draw_results(f: &mut Frame, area: Rect, app: &App) {
    let ra = Rect::new(5, 2, area.width.saturating_sub(10), area.height.saturating_sub(4));
    let chart_h = ra.height.saturating_sub(3);
    let chart_area = Rect::new(ra.x, ra.y, ra.width, chart_h);
    let stats_y = ra.y + chart_h;
    let hint_y = ra.y + chart_h + 2;

    let n = app.samples.len() as f64;
    let ymax = if app.samples.is_empty() { f64::INFINITY } else { app.max_wpm() };
    let xmax = if n < 1.0 { 1.0 } else { n };
    let data: Vec<(f64, f64)> = app.samples.clone();
    let ds = Dataset::default().data(&data).marker(Marker::Braille).graph_type(GraphType::Line).style(Style::default().fg(MAGENTA));
    let chart = Chart::new(vec![ds])
        .x_axis(Axis::default().title("seconds").bounds([1.0, xmax])
                .labels(vec![Span::styled("1", Style::default().add_modifier(Modifier::BOLD)),
                             Span::styled(format!("{:.2}", xmax), Style::default().add_modifier(Modifier::BOLD))]))
        .y_axis(Axis::default().title("wpm").bounds([0.0, ymax])
                .labels(vec![Span::styled("0", Style::default().add_modifier(Modifier::BOLD)),
                             Span::styled(fmt_num(ymax), Style::default().add_modifier(Modifier::BOLD))]));
    f.render_widget(chart, chart_area);

    let wpm = app.wpm();
    let stats = format!("{} wpm   {}% acc   {:.2} sd", fmt_num(wpm), fmt_num(app.accuracy().round()), app.std_dev());
    let sw = stats.chars().count();
    let sx = ((ra.width as f64 / 2.0) as usize).saturating_sub((sw as f64 / 2.0) as usize);
