use crate::cli::{Args, Lang};

const GREEN: Color = Color::Indexed(2);
const RED: Color = Color::Indexed(1);
const MAGENTA: Color = Color::Indexed(5);

pub struct App {
    pub prompt: Vec<char>,
    pub typed: Vec<char>,
    pub correct: usize,
    pub start: Option<Instant>,
    pub secs: Option<usize>,
    pub samples: Vec<(f64, f64)>,
    pub last_sample: usize,
    pub last_key_elapsed: f64,
    pub finished: bool,
    pub words: Vec<String>,
    pub lang: Lang,
    pub num_words: usize,
}

impl App {
    pub fn wpm(&self) -> f64 {
        let n = self.samples.len();
        if n == 0 { return f64::INFINITY; }
        (self.correct as f64) * 12.0 / (n as f64)
    }
    pub fn accuracy(&self) -> f64 {
        (self.correct as f64) / (self.prompt.len() as f64) * 100.0
    }
    pub fn std_dev(&self) -> f64 {
        let ys: Vec<f64> = self.samples.iter().map(|p| p.1).collect();
        if ys.is_empty() { return 0.0; }
        let n = ys.len() as f64;
        let mean = ys.iter().sum::<f64>() / n;
        let var = ys.iter().map(|y| (y - mean) * (y - mean)).sum::<f64>() / n;
        var.sqrt()
    }
    pub fn max_wpm(&self) -> f64 {
        self.samples.iter().map(|p| p.1).fold(f64::NEG_INFINITY, f64::max)
    }
}

fn new_prompt(args: &Args) -> Vec<char> {
    if let Some(p) = &args.prompt {
        return p.chars().collect();
    }
    if let Some(n) = args.full_sentences {
        return sentences(n);
    }
    let list: Vec<&str> = args.lang.words().split_whitespace().collect();
    let n = args.num_words.min(list.len());
    // sample n distinct words (without replacement)
    let mut idx: Vec<usize> = (0..list.len()).collect();
    shuffle(&mut idx);
    idx.truncate(n);
    let s: Vec<&str> = idx.iter().map(|&i| list[i]).collect();
    s.join(" ").chars().collect()
}

// xorshift RNG so we don't need the `rand` crate
struct Rng(u64);
impl Rng {
    fn new() -> Self { Rng(0x9E3779B97F4A7C15 ^ (std::process::id() as u64).wrapping_mul(0xBF58476D1CE4E5B9)) }
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize { (self.next() % (n as u64).max(1)) as usize }
}
fn shuffle(v: &mut [usize]) {
    let mut r = Rng::new();
    for i in (1..v.len()).rev() {
        let j = r.below(i + 1);
        v.swap(i, j);
    }
}

const HELP_START: &str = "Start of help text: ";
fn sentences(_n: usize) -> Vec<char> {
    // placeholder, replaced below
    Vec::new()
}

pub fn run(args: Args) {
    let mut app = App {
        prompt: new_prompt(&args),
        typed: Vec::new(),
        correct: 0,
        start: None,
        secs: args.secs,
        samples: Vec::new(),
        last_sample: 0,
        last_key_elapsed: 0.0,
        finished: false,
        words: Vec::new(),
        lang: args.lang,
        num_words: args.num_words,
    };
    let mut custom = args.prompt.is_some();
    let _ = &mut custom;

    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).unwrap();
    crossterm::terminal::enable_raw_mode().unwrap();
    let backend = CrosstermBackend::new(stdout);
    let mut term = Terminal::new(backend).unwrap();
    term.hide_cursor().unwrap();

    let tick = Duration::from_millis(100);
    let mut last_tick = Instant::now();
    let mut quit = false;

    loop {
        let timeout = tick.saturating_sub(last_tick.elapsed());
        if event::poll(timeout).unwrap() {
            if let Event::Key(KeyEvent { code, modifiers, .. }) = event::read().unwrap() {
                if let Some(q) = handle_key(&mut app, code, modifiers) {
                    quit = q;
                }
            }
            last_tick = Instant::now();
        } else if last_tick.elapsed() >= tick {
            on_tick(&mut app);
            last_tick = Instant::now();
        }
        if quit { break; }
        term.draw(|f| draw(f, &app)).unwrap();
        if app.finished {
            // log and go to results view handled by state
        }
    }

    crossterm::terminal::disable_raw_mode().unwrap();
    execute!(term.backend_mut(), LeaveAlternateScreen).unwrap();
    term.show_cursor().unwrap();
}

fn handle_key(app: &mut App, code: KeyCode, _mods: KeyModifiers) -> Option<bool> {
    match code {
        KeyCode::Esc => Some(true),
        KeyCode::Left => { restart(app); Some(false) }
        KeyCode::Right => { app.prompt = new_random(&app.lang, app.num_words); restart(app); Some(false) }
        KeyCode::Char(c) => { type_char(app, c); Some(false) }
        _ => { finish(app); Some(false) }
    }
}

fn new_random(lang: &Lang, num_words: usize) -> Vec<char> {
    let list: Vec<&str> = lang.words().split_whitespace().collect();
    let n = num_words.min(list.len());
    let mut idx: Vec<usize> = (0..list.len()).collect();
    shuffle(&mut idx);
    idx.truncate(n);
    let s: Vec<&str> = idx.iter().map(|&i| list[i]).collect();
    s.join(" ").chars().collect()
}

fn restart(app: &mut App) {
    app.typed.clear();
    app.correct = 0;
    app.start = None;
    app.samples.clear();
    app.last_sample = 0;
    app.last_key_elapsed = 0.0;
    app.finished = false;
}

fn type_char(app: &mut App, c: char) {
    if app.finished { return; }
    if app.start.is_none() { app.start = Some(Instant::now()); }
    let i = app.typed.len();
    if i < app.prompt.len() {
        if app.prompt[i] == c { app.correct += 1; }
        app.typed.push(c);
        app.last_key_elapsed = app.start.unwrap().elapsed().as_secs_f64();
    }
    if app.typed.len() >= app.prompt.len() {
        finish(app);
    }
}

fn finish(app: &mut App) {
    if app.finished { return; }
    app.finished = true;
    log_result(app);
}

fn on_tick(app: &mut App) {
    // timeout check
    if let (Some(start), Some(secs)) = (app.start, app.secs) {
        let el = start.elapsed().as_secs_f64();
        if el >= secs as f64 {
            app.last_key_elapsed = el;
            finish(app);
            return;
        }
    }
    // sampling
    if let Some(start) = app.start {
        let el = start.elapsed().as_secs_f64();
        let limit = app.last_key_elapsed + 1.0;
        while (app.last_sample + 1) as f64 <= el.min(limit) {
            app.last_sample += 1;
            let t = app.last_sample as f64;
            let chars = app.typed.iter().take_while(|_| true).count();
            let _ = chars;
            let typed_at = app.typed_at(t);
            let y = typed_at as f64 / 5.0 / (t / 60.0);
            app.samples.push((t, y));
        }
    }
}

