    pub samples: Vec<(f64, f64)>,
    pub last_sample: usize,
    pub last_key_elapsed: f64,
    pub finished: bool,
    pub words: Vec<String>,
    pub lang: Lang,
    pub num_words: usize,
}

impl App {
    pub fn wpm(&self) -> f64 {
        let n = self.samples.len();
        if n == 0 { return f64::INFINITY; }
        (self.correct as f64) * 12.0 / (n as f64)
    }
    pub fn accuracy(&self) -> f64 {
        (self.correct as f64) / (self.prompt.len() as f64) * 100.0
    }
    pub fn std_dev(&self) -> f64 {
        let ys: Vec<f64> = self.samples.iter().map(|p| p.1).collect();
        if ys.is_empty() { return 0.0; }
        let n = ys.len() as f64;
        let mean = ys.iter().sum::<f64>() / n;
        let var = ys.iter().map(|y| (y - mean) * (y - mean)).sum::<f64>() / n;
        var.sqrt()
    }
    pub fn max_wpm(&self) -> f64 {
        self.samples.iter().map(|p| p.1).fold(f64::NEG_INFINITY, f64::max)
    }
}

fn new_prompt(args: &Args) -> Vec<char> {
    if let Some(p) = &args.prompt {
        return p.chars().collect();
    }
    if let Some(n) = args.full_sentences {
        return sentences(n);
    }
    let list: Vec<&str> = args.lang.words().split_whitespace().collect();
    let n = args.num_words.min(list.len());
    // sample n distinct words (without replacement)
    let mut idx: Vec<usize> = (0..list.len()).collect();
    shuffle(&mut idx);
    idx.truncate(n);
    let s: Vec<&str> = idx.iter().map(|&i| list[i]).collect();
    s.join(" ").chars().collect()
}

