        while (app.last_sample + 1) as f64 <= el.min(limit) {
            app.last_sample += 1;
            let t = app.last_sample as f64;
            let c = app.typed_at(t) as f64;
            let y = c / 5.0 / (t / 60.0);
            app.samples.push(y);
        }
    }
}

