fn wrap_lines(text: &[char], width: usize) -> Vec<Vec<char>> {
    let mut out: Vec<Vec<char>> = Vec::new();
    if width == 0 { out.push(text.to_vec()); return out; }
    let mut cur: Vec<char> = Vec::new();
    let mut i = 0usize;
    while i < text.len() {
        // word
        let start = i;
        while i < text.len() && text[i] != ' ' { i += 1; }
        let word: Vec<char> = text[start..i].to_vec();
        // trailing separator spaces
        let mut sp = 0usize;
        while i < text.len() && text[i] == ' ' { sp += 1; i += 1; }
        if cur.is_empty() {
            if word.len() > width {
                let mut k = 0;
                while k + width < word.len() {
                    out.push(word[k..k + width].to_vec());
                    k += width;
                }
                cur = word[k..].to_vec();
            } else {
                cur = word.clone();
            }
        } else if cur.len() + 1 + word.len() <= width {
            cur.push(' ');
            cur.extend(word.iter().copied());
        } else {
            out.push(std::mem::take(&mut cur));
            if word.len() > width {
                let mut k = 0;
                while k + width < word.len() {
                    out.push(word[k..k + width].to_vec());
                    k += width;
                }
                cur = word[k..].to_vec();
            } else {
                cur = word.clone();
            }
        }
        let _ = sp;
    }
    if !cur.is_empty() { out.push(cur); }
    if out.is_empty() { out.push(Vec::new()); }
    out
}

fn base_y(h: u16, n: usize) -> u16 {
    let c = if n <= 1 { 1usize } else { n + 1 };
    let v = (h as i32 - c as i32) / 2;
    if v < 0 { 0 } else { v as u16 }
}

fn draw_test(f: &mut Frame, area: Rect, app: &App) {
    let w = area.width as usize;
    let maxw = if w > 10 { (w - 10).min(MAX_LINE) } else { 1 };
    let lines = wrap_lines(&app.prompt, maxw);
    let n = lines.len();
    let blockw = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    let x = ((w as f64) / 2.0) as usize - ((blockw as f64) / 2.0) as usize;
    let y = base_y(area.height, n);
    let has_timer = app.secs.is_some();
    let py = y + if has_timer { 2 } else { 0 };
    if has_timer {
        let remaining = match (app.start, app.secs) {
            (Some(s), Some(v)) => (v as f64 - s.elapsed().as_secs_f64()).max(0.0),
            _ => app.secs.unwrap() as f64,
        };
        let s = format!("{:.1}", remaining);
        let sw = s.chars().count();
        let tx = ((area.width as f64) / 2.0) as usize - ((sw as f64) / 2.0) as usize;
        let style = Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM);
        f.render_widget(Line::from(Span::styled(s, style)),
                        Rect::new(tx as u16, y, area.width, 1));
    }
    for (i, l) in lines.iter().enumerate() {
        if py + i as u16 >= area.height { break; }
        let mut spans: Vec<Span> = Vec::new();
        let base = lines.iter().take(i).map(|l| l.len() + 1).sum::<usize>();
        for (j, ch) in l.iter().enumerate() {
            let abs = base + j;
            let style = if abs < app.typed.len() {
                if app.typed[abs] == *ch {
                    Style::default().fg(GREEN).add_modifier(Modifier::BOLD)
                } else {
                    let shown = if *ch == ' ' { '\u{00b7}' } else { *ch };
                    spans.push(Span::styled(shown.to_string(),
                                            Style::default().fg(RED).add_modifier(Modifier::BOLD)));
                    continue;
                }
            } else if abs == app.typed.len() {
                Style::default().add_modifier(Modifier::BOLD)
                    .add_modifier(Modifier::DIM).add_modifier(Modifier::UNDERLINE)
            } else {
                Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM)
            };
            spans.push(Span::styled(ch.to_string(), style));
        }
        f.render_widget(Line::from(spans), Rect::new(x as u16, (py + i) as u16, area.width, 1));
    }
}

fn draw_results(f: &mut Frame, area: Rect, app: &App) {
    let rw = area.width.saturating_sub(10);
    let rh = area.height.saturating_sub(4);
    if rw == 0 || rh == 0 { return; }
    let ra = Rect::new(5, 2, rw, rh);
    let chart_h = rh.saturating_sub(3);
    if chart_h == 0 { return; }
    let chart_area = Rect::new(ra.x, ra.y, rw, chart_h);
    let stats_y = ra.y + chart_h;
    let hint_y = ra.y + chart_h + 2;

    let xmax = app.xmax();
    let ymax = app.ymax();
    let data: Vec<(f64, f64)> = app.samples.iter().enumerate().map(|(i, y)| ((i + 1) as f64, *y)).collect();
    let ds = Dataset::default().data(&data).marker(Marker::Braille)
        .graph_type(GraphType::Line).style(Style::default().fg(MAGENTA));
    let bold = Style::default().add_modifier(Modifier::BOLD);
    let chart = Chart::new(vec![ds])
        .x_axis(Axis::default().title("seconds").bounds([1.0, xmax])
                .labels(vec![Span::styled("1", bold), Span::styled(format!("{:.2}", xmax), bold)]))
        .y_axis(Axis::default().title("wpm").bounds([0.0, ymax])
                .labels(vec![Span::styled("0", bold), Span::styled(fmt_num(ymax), bold)]));
    f.render_widget(chart, chart_area);

    let stats = format!("{} wpm   {}% acc   {:.2} sd", fmt_num(app.wpm()),
                        fmt_num(app.accuracy().round()), app.std_dev());
    let sw = stats.chars().count();
    let sx = ((rw as f64) / 2.0) as usize - ((sw as f64) / 2.0) as usize;
    f.render_widget(Line::from(Span::styled(stats, bold)),
                    Rect::new((ra.x as usize + sx) as u16, stats_y, rw, 1));
    let hint = "(r)etry / (n)ew / (esc)ape";
    f.render_widget(Line::from(Span::styled(hint, Style::default().add_modifier(Modifier::ITALIC))),
                    Rect::new(ra.x, hint_y, rw, 1));
}

fn fmt_num(v: f64) -> String {
    if v.is_nan() { "NaN".into() }
    else if v.is_infinite() { if v < 0.0 { "-inf".into() } else { "inf".into() } }
    else if v == v.floor() && v.abs() < 1e15 { format!("{}", v as i64) }
    else { format!("{}", v) }
}

fn log_result(app: &App) {
    use std::fs::OpenOptions;
    let Some(dir) = dirs::config_dir().map(|d| d.join("thokr")) else { return };
    let _ = std::fs::create_dir_all(&dir);
    let path = dir.join("log.csv");
    let exists = path.exists();
    if let Ok(mut fh) = OpenOptions::new().create(true).append(true).open(&path) {
        if !exists {
            let _ = writeln!(fh, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev");
        }
        let date = chrono::Local::now().format("%a %b %e %H:%M:%S %Y");
