        let _ = writeln!(fh, "{},{},{},{:.2},{},{},{:.2}", date, app.num_words, secs,
                         app.last_key_elapsed, fmt_num(app.wpm().ceil()),
                         fmt_num(app.accuracy().round()), app.std_dev());
    }
}
