use std::io::{self, Write};
use std::time::{Duration, Instant};

use ratatui::backend::CrosstermBackend;
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Axis, Chart, Dataset, GraphType};
use ratatui::symbols::Marker;
use ratatui::{Frame, Terminal};
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use crossterm::execute;
use crossterm::terminal::{EnterAlternateScreen, LeaveAlternateScreen};

use crate::cli::{Args, Lang};

const GREEN: Color = Color::Indexed(2);
const RED: Color = Color::Indexed(1);
const MAGENTA: Color = Color::Indexed(5);
const MAX_LINE: usize = 1800;

pub struct App {
    pub prompt: Vec<char>,
    pub typed: Vec<char>,
    pub correct: usize,
    pub start: Option<Instant>,
    pub secs: Option<usize>,
    pub events: Vec<(f64, char)>,
    pub samples: Vec<f64>,
    pub last_sample: usize,
    pub last_key_elapsed: f64,
    pub finished: bool,
    pub lang: Lang,
    pub num_words: usize,
    pub full_sentences: Option<usize>,
    pub prompt_kind: PromptKind,
}

#[derive(Clone, Copy, PartialEq)]
pub enum PromptKind { Custom, Words, Sentences }

impl App {
    pub fn wpm(&self) -> f64 {
        let n = self.samples.len();
        if n == 0 { return f64::INFINITY; }
        (self.correct as f64) * 12.0 / (n as f64)
    }
    pub fn accuracy(&self) -> f64 {
        (self.correct as f64) / (self.prompt.len() as f64) * 100.0
    }
    pub fn std_dev(&self) -> f64 {
        let ys: Vec<f64> = self.samples.clone();
        if ys.is_empty() { return 0.0; }
        let n = ys.len() as f64;
        let mean = ys.iter().sum::<f64>() / n;
        let var = ys.iter().map(|y| (y - mean) * (y - mean)).sum::<f64>() / n;
        var.sqrt()
    }
    pub fn ymax(&self) -> f64 {
        if self.samples.is_empty() { return f64::INFINITY; }
        self.samples.iter().copied().fold(f64::NEG_INFINITY, f64::max)
    }
    pub fn xmax(&self) -> f64 {
        let n = self.samples.len();
        if n == 0 { 1.0 } else { n as f64 }
    }
    pub fn typed_at(&self, t: f64) -> usize {
        self.events.iter().take_while(|(e, _)| *e < t).count()
    }
}

struct Rng(u64);
impl Rng {
    fn new() -> Self {
        let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos() as u64;
        Rng(0x9E3779B97F4A7C15 ^ t ^ ((std::process::id() as u64) << 32))
    }
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        if n == 0 { 0 } else { (self.next() % n as u64) as usize }
    }
}

fn shuffle(v: &mut [usize]) {
    let mut r = Rng::new();
    for i in (1..v.len()).rev() {
        let j = r.below(i + 1);
        v.swap(i, j);
    }
}

fn word_prompt(lang: &Lang, num_words: usize) -> Vec<char> {
    let list: Vec<&str> = lang.words().split_whitespace().collect();
    let n = num_words.min(list.len()).max(1);
    let mut idx: Vec<usize> = (0..list.len()).collect();
    shuffle(&mut idx);
    idx.truncate(n);
    let s: Vec<&str> = idx.iter().map(|&i| list[i]).collect();
    s.join(" ").chars().collect()
}

fn sentence_prompt(n: usize) -> Vec<char> {
    let s = crate::sentences::make(n);
    s.chars().collect()
}

pub fn make_prompt(args: &Args) -> (Vec<char>, PromptKind) {
    if let Some(p) = &args.prompt { return (p.chars().collect(), PromptKind::Custom); }
    if let Some(n) = args.full_sentences { return (sentence_prompt(n), PromptKind::Sentences); }
    (word_prompt(&args.lang, args.num_words), PromptKind::Words)
}

pub fn run(args: Args) {
    let (prompt, kind) = make_prompt(&args);
    let mut app = App {
        prompt,
        typed: Vec::new(),
        correct: 0,
        start: None,
        secs: args.secs,
        events: Vec::new(),
        samples: Vec::new(),
        last_sample: 0,
        last_key_elapsed: 0.0,
        finished: false,
        lang: args.lang,
        num_words: args.num_words,
        full_sentences: args.full_sentences,
        prompt_kind: kind,
    };

    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).unwrap();
    crossterm::terminal::enable_raw_mode().unwrap();
    let backend = CrosstermBackend::new(stdout);
    let mut term = Terminal::new(backend).unwrap();
    let _ = term.hide_cursor();

    let tick = Duration::from_millis(100);
    let mut last_tick = Instant::now();
    let mut quit = false;

    while !quit {
        let timeout = tick.saturating_sub(last_tick.elapsed());
        let mut got_event = false;
        if event::poll(timeout).unwrap() {
            if let Event::Key(KeyEvent { code, modifiers, .. }) = event::read().unwrap() {
                quit = handle_key(&mut app, code, modifiers);
                got_event = true;
            }
        }
        if !got_event && last_tick.elapsed() >= tick {
            on_tick(&mut app);
        }
        last_tick = Instant::now();
        term.draw(|f| draw(f, &app)).unwrap();
    }

    crossterm::terminal::disable_raw_mode().unwrap();
    execute!(term.backend_mut(), LeaveAlternateScreen).unwrap();
    let _ = term.show_cursor();
}

fn handle_key(app: &mut App, code: KeyCode, _mods: KeyModifiers) -> bool {
    if app.finished {
        match code {
            KeyCode::Esc => return true,
            KeyCode::Char('r') => { restart(app); }
            KeyCode::Char('n') => {
                app.prompt = match app.prompt_kind {
                    PromptKind::Custom => crate::sentences::none_chars(),
                    _ => new_prompt_again(app),
                };
                restart(app);
            }
            _ => {}
        }
        return false;
    }
    match code {
        KeyCode::Esc => true,
        KeyCode::Left => { restart(app); false }
        KeyCode::Right => { app.prompt = new_prompt_again(app); restart(app); false }
        KeyCode::Char(c) => { type_char(app, c); false }
        _ => { finish(app); false }
    }
}

fn new_prompt_again(app: &App) -> Vec<char> {
    match app.prompt_kind {
        PromptKind::Custom => word_prompt(&app.lang, app.num_words),
        PromptKind::Sentences => sentence_prompt(app.full_sentences.unwrap_or(1)),
        PromptKind::Words => word_prompt(&app.lang, app.num_words),
    }
}

fn restart(app: &mut App) {
    app.typed.clear();
    app.correct = 0;
    app.start = None;
    app.events.clear();
    app.samples.clear();
    app.last_sample = 0;
    app.last_key_elapsed = 0.0;
    app.finished = false;
}

fn type_char(app: &mut App, c: char) {
    if app.finished { return; }
    if app.start.is_none() { app.start = Some(Instant::now()); }
    let i = app.typed.len();
    if i < app.prompt.len() {
        if app.prompt[i] == c { app.correct += 1; }
        app.typed.push(c);
        app.last_key_elapsed = app.start.unwrap().elapsed().as_secs_f64();
        app.events.push((app.last_key_elapsed, c));
    }
    if app.typed.len() >= app.prompt.len() { finish(app); }
}

fn finish(app: &mut App) {
    if app.finished { return; }
    app.finished = true;
    log_result(app);
}

fn on_tick(app: &mut App) {
    if let (Some(start), Some(secs)) = (app.start, app.secs) {
        let el = start.elapsed().as_secs_f64();
        if el >= secs as f64 {
            app.last_key_elapsed = el;
            finish(app);
            return;
        }
    }
    if let Some(start) = app.start {
        let el = start.elapsed().as_secs_f64();
        let limit = app.last_key_elapsed + 1.0;
        while (app.last_sample + 1) as f64 <= el.min(limit) {
            app.last_sample += 1;
            let t = app.last_sample as f64;
            let c = app.typed_at(t) as f64;
            let y = c / 5.0 / (t / 60.0);
            app.samples.push(y);
        }
    }
}

