{"command": "cd /workspace && cat > src/cli.rs <<'RSEOF'
use std::process::exit;

pub const VERSION: &str = "thokr 0.4.1";
pub const ABOUT: &str = "sleek typing tui with visualized results and historical logging";
const NAME: &str = "thokr";

#[derive(Clone, Copy, PartialEq)]
pub enum Lang { English, English1k, English10k }

impl Lang {
    pub fn words(&self) -> &'static str {
        match self {
            Lang::English => include_str!("words/english.txt"),
            Lang::English1k => include_str!("words/english1k.txt"),
            Lang::English10k => include_str!("words/english10k.txt"),
        }
    }
}

pub struct Args {
    pub full_sentences: Option<usize>,
    pub lang: Lang,
    pub prompt: Option<String>,
    pub secs: Option<usize>,
    pub num_words: usize,
}

struct Opt {
    short: char,
    long: &'static str,
    value: Option<&'static str>,
    help: &'static str,
    default: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
}

const OPTS: &[Opt] = &[
    Opt { short: 'f', long: "full-sentences", value: Some("NUMBER_OF_SENTENCES"),
          help: "number of sentences to use in test", default: None, possible: None },
    Opt { short: 'h', long: "help", value: None, help: "Print help information",
          default: None, possible: None },
    Opt { short: 'l', long: "supported-language", value: Some("SUPPORTED_LANGUAGE"),
          help: "language to pull words from", default: Some("english"),
          possible: Some(&["english", "english1k", "english10k"]) },
    Opt { short: 'p', long: "prompt", value: Some("PROMPT"), help: "custom prompt to use",
          default: None, possible: None },
    Opt { short: 's', long: "number-of-secs", value: Some("NUMBER_OF_SECS"),
          help: "number of seconds to run test", default: None, possible: None },
    Opt { short: 'V', long: "version", value: None, help: "Print version information",
          default: None, possible: None },
    Opt { short: 'w', long: "number-of-words", value: Some("NUMBER_OF_WORDS"),
          help: "number of words to use in test", default: Some("15"), possible: None },
];

#[repr(C)]
struct Winsize { row: u16, col: u16, x: u16, y: u16 }
extern "C" {
    fn isatty(fd: i32) -> i32;
    fn ioctl(fd: i32, req: u64, ...) -> i32;
}
fn is_tty(fd: i32) -> bool { unsafe { isatty(fd) != 0 } }

fn term_width() -> usize {
    if is_tty(1) {
        let mut ws = Winsize { row: 0, col: 0, x: 0, y: 0 };
        unsafe {
            if ioctl(1, 0x5413, &mut ws as *mut Winsize) == 0 && ws.col > 0 { return ws.col as usize; }
        }
    }
    80
}

// --- colour helpers -------------------------------------------------------
fn hcolor(s: &str, code: &str) -> String {           // help colours (stdout)
    if is_tty(1) { format!("\x1b[{}m{}\x1b[39m", code, s) } else { s.to_string() }
}
fn eerr(s: &str) -> String {                          // "error:" bold red (stderr)
    if is_tty(2) { format!("\x1b[1m\x1b[31m{}\x1b[0m\x1b[39m\x1b[49m", s) } else { s.to_string() }
}
fn egreen(s: &str) -> String {
    if is_tty(2) { format!("\x1b[32m{}\x1b[39m", s) } else { s.to_string() }
}
fn eyellow(s: &str) -> String {
    if is_tty(2) { format!("\x1b[33m{}\x1b[39m", s) } else { s.to_string() }
}

// --- text wrapping --------------------------------------------------------
fn wrap_body(text: &str, width: usize) -> Vec<String> {
    // clap-like wrapping: greedy on spaces; a word longer than the line is
    // hard split.  Reproduces the odd behaviour of the `[possible values: ]`
    // suffix: when the text overflows, the last possible value is pushed to
    // its own (indented) line while intermediate overflow lines are not
    // indented.
    if text.chars().count() <= width {
        return vec![text.to_string()];
    }
    let mut out: Vec<String> = Vec::new();
    // hard-wrap the first chunk to `width` characters
    let chars: Vec<char> = text.chars().collect();
    out.push(chars[..width].iter().collect());
    let mut rest: String = chars[width..].iter().collect();
    // if the remainder still contains a `[possible values: ...]` tail whose
    // last element should be on its own line
    if let Some(pos) = rest.rfind(", ") {
        // split before the final element
        let (head, tail) = rest.split_at(pos + 2);
        if tail.chars().count() <= width {
            out.push(head.trim_end().to_string());
            out.push(tail.to_string());
            return out;
        }
    }
    // greedy wrap of the remainder (unindented)
    let mut cur = String::new();
    for word in rest.split(' ') {
        if cur.is_empty() {
            cur = word.to_string();
        } else if cur.chars().count() + 1 + word.chars().count() <= width {
            cur.push(' '); cur.push_str(word);
        } else {
            out.push(std::mem::take(&mut cur));
            cur = word.to_string();
        }
    }
    if !cur.is_empty() { out.push(cur); }
    out
}

fn help_text(bin: &str) -> String {
    let width = term_width();
    let mut out = String::new();
    out.push_str(&format!("{} {}\n", hcolor(NAME, "32"), &VERSION[NAME.len() + 1..]));
    out.push_str(&wrap_body(ABOUT, width).join("\n"));
    out.push_str("\n\n");
    out.push_str(&format!("{}\n", hcolor("USAGE:", "33")));
    out.push_str(&format!("    {} [OPTIONS]\n\n", bin));
    out.push_str(&format!("{}\n", hcolor("OPTIONS:", "33")));
    for (i, o) in OPTS.iter().enumerate() {
        let mut head = format!("    {}, {}", hcolor(&format!("-{}", o.short), "32"),
                               hcolor(&format!("--{}", o.long), "32"));
        if let Some(v) = o.value {
            head.push_str(&format!(" {}", hcolor(&format!("<{}>", v), "32")));
        }
        out.push_str(&head);
        out.push('\n');
        let mut body = String::from(o.help);
        if let Some(d) = o.default { body.push_str(&format!(" [default: {}]", d)); }
        if let Some(p) = o.possible { body.push_str(&format!(" [possible values: {}]", p.join(", "))); }
        let w = width.saturating_sub(12);
        for line in wrap_body(&body, w.max(1)) {
            out.push_str(&format!("            {}\n", line));
        }
        if i + 1 < OPTS.len() { out.push('\n'); }
    }
    out
}

fn usage_block(bin: &str, smart: Option<String>) -> String {
    let mut s = String::from("\nUSAGE:\n    ");
    match smart { Some(x) => s.push_str(&format!("{} {}\n", bin, x)), None => s.push_str(&format!("{} [OPTIONS]\n", bin)) }
    s
}

fn emit(out: String) -> ! {
    eprint!("{}", out);
    exit(2);
}

fn unknown_arg(bin: &str, arg: &str, long: bool, smart: Option<String>) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} Found argument '{}' which wasn't expected, or isn't valid in this context\n",
                          eerr("error:"), eyellow(arg)));
    if let Some(c) = smart {
        out.push('\n');
        out.push_str(&format!("\tDid you mean '{}'?\n", egreen(&c)));
    }
    if arg.starts_with('-') {
        out.push('\n');
        out.push_str(&format!("\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n", arg, arg));
    }
    out.push_str(&usage_block(bin, smart));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

fn suggestion(arg: &str) -> Option<String> {
    if !arg.starts_with("--") { return None; }
    let mut best: Option<(usize, String)> = None;
    for o in OPTS {
        let c = format!("--{}", o.long);
        let d = levenshtein(arg, &c);
        if best.as_ref().map_or(true, |(bd, _)| d < *bd) { best = Some((d, c)); }
    }
    match best {
        Some((d, c)) if d <= 2 => Some(c),
        _ => None,
    }
}

fn levenshtein(a: &str, b: &str) -> usize {
    let av: Vec<char> = a.chars().collect();
    let bv: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=bv.len()).collect();
    for (i, ca) in av.iter().enumerate() {
        let mut cur = vec![i + 1];
        for (j, cb) in bv.iter().enumerate() {
            let cost = if ca == cb { 0 } else { 1 };
            cur.push((prev[j] + cost).min(cur[j] + 1).min(prev[j + 1] + 1));
        }
        prev = cur;
    }
    prev[bv.len()]
}

fn missing_value(bin: &str, o: &Opt) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} The argument '{}' requires a value but none was supplied\n",
                          eerr("error:"), eyellow(&format!("--{} <{}>", o.long, o.value.unwrap_or("")))));
    if let Some(p) = o.possible {
        let vals: Vec<String> = p.iter().map(|v| egreen(v)).collect();
        out.push_str(&format!("\t[possible values: {}]\n", vals.join(", ")));
    }
    out.push_str(&usage_block(bin, None));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

fn dup_value(bin: &str, o: &Opt) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} The argument '{}' was provided more than once, but cannot be used multiple times\n",
                          eerr("error:"), eyellow(&format!("--{} <{}>", o.long, o.value.unwrap_or("")))));
    out.push_str(&usage_block(bin, None));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

fn invalid_value(bin: &str, o: &Opt, val: &str, reason: &str) -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} Invalid value \"{}\" for '{}': {}\n",
                          eerr("error:"), val,
                          eyellow(&format!("--{} <{}>", o.long, o.value.unwrap_or(""))), reason));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

fn bad_lang(bin: &str, o: &Opt, val: &str) -> ! {
    let p = o.possible.unwrap();
    let mut out = String::new();
    out.push_str(&format!("{} \"{}\" isn't a valid value for '{}'\n",
                          eerr("error:"), val, eyellow(&format!("--{} <{}>", o.long, o.value.unwrap_or("")))));
    let vals: Vec<String> = p.iter().map(|v| egreen(v)).collect();
    out.push_str(&format!("\t[possible values: {}]\n", vals.join(", ")));
    out.push_str(&usage_block(bin, Some(format!("--{} <{}>", o.long, o.value.unwrap_or("")))));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

pub fn tty_error() -> ! {
    let mut out = String::new();
    out.push_str(&format!("{} stdin must be a tty\n", eerr("error:")));
    out.push_str(&usage_block(NAME, None));
    out.push_str(&format!("\nFor more information try {}\n", egreen("--help")));
    emit(out)
}

struct State {
    full_sentences: Option<usize>,
    secs: Option<usize>,
    prompt: Option<String>,
    lang: Option<String>,
    num_words: Option<usize>,
    seen: Vec<&'static str>,
}

fn store(bin: &str, st: &mut State, o: &'static Opt, val: &str) {
    if st.seen.contains(&o.long) { dup_value(bin, o); }
    st.seen.push(o.long);
    match o.long {
        "full-sentences" => st.full_sentences = Some(parse_num(bin, o, val)),
        "number-of-secs" => st.secs = Some(parse_num(bin, o, val)),
        "number-of-words" => st.num_words = Some(parse_num(bin, o, val)),
        "prompt" => st.prompt = Some(val.to_string()),
        "supported-language" => {
            let p = o.possible.unwrap();
            if !p.contains(&val) { bad_lang(bin, o, val); }
            st.lang = Some(val.to_string());
        }
        _ => {}
    }
}

fn parse_num(bin: &str, o: &'static Opt, val: &str) -> usize {
    match val.parse::<usize>() {
        Ok(v) => v,
        Err(_) => {
            let digits = !val.is_empty() && val.chars().all(|c| c.is_ascii_digit());
            let reason = if digits { "number too large to fit in target type" } else { "invalid digit found in string" };
            invalid_value(bin, o, val, reason)
        }
    }
}

pub fn parse() -> Args {
    let argv: Vec<String> = std::env::args().collect();
    let bin = argv.first().map(|s| std::path::Path::new(s).file_name()
            .map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| s.clone()))
        .unwrap_or_else(|| NAME.to_string());
    let args: Vec<String> = argv.into_iter().skip(1).collect();

    let mut st = State { full_sentences: None, secs: None, prompt: None, lang: None,
                         num_words: None, seen: Vec::new() };
    let mut i = 0usize;
    let mut positional_only = false;

    while i < args.len() {
        let a = args[i].clone();
        if !positional_only && a == "--" { positional_only = true; i += 1; continue; }
        if !positional_only && a.starts_with("--") {
            let (name, inline) = match a[2..].split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (a[2..].to_string(), None),
            };
            if name == "help" { print!("{}", help_text(&bin)); exit(0); }
            if name == "version" { println!("{}", VERSION); exit(0); }
            match OPTS.iter().find(|o| o.long == name) {
                None => unknown_arg(&bin, &a, true, suggestion(&a)),
                Some(o) => {
                    let val = match inline {
                        Some(v) => v,
                        None => {
                            i += 1;
                            if i >= args.len() { missing_value(&bin, o); }
                            if args[i].starts_with('-') && args[i].len() > 1 {
                                let bad = args[i].clone();
                                unknown_arg(&bin, &bad, true, suggestion(&bad));
                            }
                            args[i].clone()
                        }
                    };
                    store(&bin, &mut st, o, &val);
                    i += 1;
                }
            }
            continue;
        }
        if !positional_only && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a.chars().skip(1).collect();
            let mut j = 0usize;
            while j < chars.len() {
                let c = chars[j];
                if c == 'h' { print!("{}", help_text(&bin)); exit(0); }
                if c == 'V' { println!("{}", VERSION); exit(0); }
                match OPTS.iter().find(|o| o.short == c) {
                    None => {
                        let bad: String = std::iter::once('-').chain(chars[j..].iter().copied()).collect();
                        unknown_arg(&bin, &bad, false, None);
                    }
                    Some(o) => {
                        if o.value.is_some() {
                            let rest: String = chars[j + 1..].iter().collect();
                            let val = if !rest.is_empty() { rest } else {
                                i += 1;
                                if i >= args.len() { missing_value(&bin, o); }
                                if args[i].starts_with('-') && args[i].len() > 1 {
                                    let bad = args[i].clone();
                                    unknown_arg(&bin, &bad, true, suggestion(&bad));
                                }
                                args[i].clone()
                            };
                            store(&bin, &mut st, o, &val);
                            j = chars.len();
                        } else { j += 1; }
                    }
                }
            }
            i += 1;
            continue;
        }
        unknown_arg(&bin, &a, false, None);
    }

    let lang = match st.lang.as_deref() {
        None => Lang::English,
        Some("english") => Lang::English,
        Some("english1k") => Lang::English1k,
        _ => Lang::English10k,
    };
    Args { full_sentences: st.full_sentences, lang, prompt: st.prompt, secs: st.secs,
           num_words: st.num_words.unwrap_or(15) }
}
