    let mut brk = width;
    // clap keeps the trailing `...]` token together: if the break falls inside
    // the final token and that token ends with ']', move the break to its start
    if let Some(&(ws, we)) = words.last() {
        if we == n && chars[n - 1] == ']' && brk > ws && brk < we { brk = ws; }
